item.content:encoded:
.tp-slide-img-overlay {
	background: rgba(255, 255, 255, 0.2);
	border-radius: 16px;
	box-shadow: 0 4px 30px rgba(0, 0, 0, 0.1);
	backdrop-filter: blur(5px);
	-webkit-backdrop-filter: blur(5px);
	border: 1px solid rgba(255, 255, 255, 0.3);
}

.tp-glossy-effect, .tp-slide-img-overlay {
	background: rgba(255, 255, 255, 0.2);
	box-shadow: 0 4px 30px rgba(0, 0, 0, 0.1);
	backdrop-filter: blur(5px);
	-webkit-backdrop-filter: blur(5px);
}

.w_100 .elementor-button {
    width: 100%;
}

.all-cards {
display: flex;
flex-direction: column; /* Arrange cards vertically in the column */
}
.card1 {
position: -webkit-sticky; /* For Safari */
position: sticky;
top: 50px; /* Offset from the top */
}
.card2 {
position: -webkit-sticky; /* For Safari */
position: sticky;
top: 100px; /* Offset from the top */
}
.card3 {
position: -webkit-sticky; /* For Safari */
position: sticky;
top: 150px; /* Offset from the top */
}
.card4 {
position: -webkit-sticky; /* For Safari */
position: sticky;
top: 200px; /* Offset from the top */
}

.themephi-blog-grid.blog--style1 .blog-meta-abs::after {
    position: absolute;
    left: 100%;
    bottom: 0;
    border-top-right-radius: 0px;
    background-color: transparent;
    z-index: 3;
    content: "";
    width: 20px;
    height: 45px;
    border-bottom-left-radius: 20px;
    box-shadow: 0px 20px 0 0 #121212;
}

.themephi-blog-grid.blog--style1 .blog-meta-abs::before {
    transform: rotate(-360deg);
    left: 0;
    top: auto;
    bottom: 100%;
    position: absolute;
    right: 100%;
    border-top-right-radius: 0px;
    background-color: transparent;
    z-index: 3;
    content: "";
    width: 20px;
    height: 40px;
    border-bottom-left-radius: 20px;
    box-shadow: 0 20px 0 0 #121212;
}
.br-12 img {
	border-radius: 12px;
}
